using TownOfHost;using TownOfHost.Roles.Core;using TownOfHost.Roles.Crewmate;using TownOfHost.Roles.Impostor;using TownOfHost.Patches.ISystemType;using UnityEngine;using Hazel;
class Program{static int passed;static void Check(bool b,string m="assertion"){if(!b)throw new Exception(m);}static void Reset(){CustomRoleManager.Initialize();PlayerCatch.Players.Clear();PlayerControl.AllPlayerControls.Clear();StepBomber.ResetAll();Locksmith.SealedVentsStatic.Clear();Coroner.AllKillRecords.Clear();Utils.Sent.Clear();CustomRoleManager.Sent.Clear();CustomRoleManager.Killed.Clear();LateTask.Pending.Clear();VentilationSystemUpdateSystemPatch.NowVentId.Clear();ShipStatus.Instance=new();AmongUsClient.Instance.AmHost=true;GameStates.IsMeeting=false;GameStates.CalledMeeting=false;GameStates.IsInTask=true;StepBomber.RoleInfo.OptionCreator();Locksmith.RoleInfo.OptionCreator();Coroner.RoleInfo.OptionCreator();}
static PlayerControl PC(byte id,CustomRoles r=CustomRoles.Crewmate){var p=new PlayerControl{PlayerId=id,Role=r,Data=new(){PlayerId=id,PlayerName="Synthetic player "+id}};p.MyPhysics=new(){myPlayer=p};PlayerCatch.Players[id]=p;PlayerControl.AllPlayerControls.Add(p);return p;}
static void Test(string n,Action a){Reset();a();passed++;Console.WriteLine("PASS "+n);}
static void Main(){
Test("role IDs distinct below NotAssigned",()=>Check(new[]{(int)CustomRoles.StepBomber,(int)CustomRoles.Locksmith,(int)CustomRoles.Coroner}.Distinct().Count()==3&&(int)CustomRoles.Coroner<500));
Test("role option roots isolated",()=>Check(new[]{StepBomber.RoleInfo.ConfigId,Locksmith.RoleInfo.ConfigId,Coroner.RoleInfo.ConfigId}.Distinct().Count()==3));
Test("bomb plant suppresses ordinary kill",()=>{var b=new StepBomber(PC(1,CustomRoles.StepBomber));var t=PC(4);var m=new MurderInfo{AttemptTarget=t};b.OnCheckMurderAsKiller(m);Check(!m.CanKill&&!m.DoKill&&StepBomber.PlantedBombs[4]==1&&b.GetProgressText().Contains("0"));});
Test("duplicate bomb cannot kill or consume twice",()=>{var b=new StepBomber(PC(1,CustomRoles.StepBomber));var t=PC(4);b.OnCheckMurderAsKiller(new(){AttemptTarget=t});StepBomber.OptionHasNormalKill.Value=1;var m=new MurderInfo{AttemptTarget=t};b.OnCheckMurderAsKiller(m);Check(!m.DoKill&&StepBomber.PlantedBombs.Count==1);});
Test("bomb target notified privately after meeting trigger",()=>{var b=new StepBomber(PC(1,CustomRoles.StepBomber));b.OnCheckMurderAsKiller(new(){AttemptTarget=PC(4)});StepBomber.CheckAndTriggerNotification(0);Check(Utils.Sent.Single().To==4&&StepBomber.IgnitedPlayers.Contains(4));});
Test("multiple bombers do not double count steps",()=>{var a=new StepBomber(PC(1,CustomRoles.StepBomber));var b=new StepBomber(PC(2,CustomRoles.StepBomber));var t=PC(4);a.OnCheckMurderAsKiller(new(){AttemptTarget=t});StepBomber.CheckAndTriggerNotification(0);a.OnFixedUpdate(a.Player);b.OnFixedUpdate(b.Player);t.transform.position=new(.4f,0);a.OnFixedUpdate(a.Player);b.OnFixedUpdate(b.Player);Check(Math.Abs(StepBomber.RemainingSteps[4]-19)<.001f);});
Test("bomb teleports do not count as steps",()=>{var a=new StepBomber(PC(1,CustomRoles.StepBomber));var t=PC(4);a.OnCheckMurderAsKiller(new(){AttemptTarget=t});StepBomber.CheckAndTriggerNotification(0);a.OnFixedUpdate(a.Player);t.transform.position=new(20,0);a.OnFixedUpdate(a.Player);Check(StepBomber.RemainingSteps[4]==20);});
Test("bomb countdown paused in meeting",()=>{var a=new StepBomber(PC(1,CustomRoles.StepBomber));var t=PC(4);a.OnCheckMurderAsKiller(new(){AttemptTarget=t});StepBomber.CheckAndTriggerNotification(0);a.OnFixedUpdate(a.Player);GameStates.IsMeeting=true;t.transform.position=new(.8f,0);a.OnFixedUpdate(a.Player);Check(StepBomber.RemainingSteps[4]==20);});
Test("bomb detonation uses host kill pipeline",()=>{var a=new StepBomber(PC(1,CustomRoles.StepBomber));var t=PC(4);a.OnCheckMurderAsKiller(new(){AttemptTarget=t});StepBomber.CheckAndTriggerNotification(0);a.OnFixedUpdate(a.Player);for(int i=1;i<=21;i++){t.transform.position=new(i*.4f,0);a.OnFixedUpdate(a.Player);}Check(CustomRoleManager.Killed.Contains(4)&&!StepBomber.PlantedBombs.ContainsKey(4));});
Test("bomb data clears between matches",()=>{var a=new StepBomber(PC(1,CustomRoles.StepBomber));a.OnCheckMurderAsKiller(new(){AttemptTarget=PC(4)});StepBomber.ResetAll();Check(StepBomber.PlantedBombs.Count==0&&StepBomber.IgnitedPlayers.Count==0);});
Test("locksmith registers vent hook per match",()=>{CustomRoleManager.OnEnterVentOthers.Clear();var a=new Locksmith(PC(1,CustomRoles.Locksmith));a.Add();Check(CustomRoleManager.OnEnterVentOthers.Contains(Locksmith.OnEnterVentOthersHook));});
Test("locksmith sealing syncs count and vent",()=>{var a=new Locksmith(PC(1,CustomRoles.Locksmith));Check(!a.OnEnterVent(a.Player.MyPhysics,7));Check(Locksmith.SealedVentsStatic.Contains(7)&&CustomRoleManager.Sent.Single().Values[0].Equals(1)&&a.Player.MyPhysics.Exits==1);});
Test("only sealed vent occupants are ejected",()=>{var a=new Locksmith(PC(1,CustomRoles.Locksmith));var same=PC(2);same.inVent=true;var other=PC(3);other.inVent=true;VentilationSystemUpdateSystemPatch.NowVentId[2]=7;VentilationSystemUpdateSystemPatch.NowVentId[3]=8;a.OnEnterVent(a.Player.MyPhysics,7);Check(same.MyPhysics.Boots==1&&other.MyPhysics.Boots==0&&other.NetTransform.Snaps==0);});
Test("sealed vent blocks future entry only to that vent",()=>{Locksmith.SealedVentsStatic.Add(7);var p=PC(4);Check(Locksmith.OnEnterVentOthersHook(p.MyPhysics,7));Check(!Locksmith.OnEnterVentOthersHook(p.MyPhysics,8));Check(p.MyPhysics.Boots==1);});
Test("door state marked dirty for Vanilla sync",()=>{var a=new Locksmith(PC(1,CustomRoles.Locksmith));var d=new Door();var sys=new DoorsSystemType();ShipStatus.Instance.AllDoors=new[]{d};ShipStatus.Instance.Systems[SystemTypes.Doors]=sys;a.OnFixedUpdate(a.Player);Check(d.IsOpen&&sys.IsDirty);});
Test("dead locksmith cannot auto-open doors",()=>{var a=new Locksmith(PC(1,CustomRoles.Locksmith));a.Player.Data.IsDead=true;var d=new Door();ShipStatus.Instance.AllDoors=new[]{d};a.OnFixedUpdate(a.Player);Check(!d.IsOpen);});
Test("locksmith reception does not erase another sealed vent",()=>{var a=new Locksmith(PC(1,CustomRoles.Locksmith));Locksmith.SealedVentsStatic.Add(8);a.ReceiveRPC(new(1,10f,1,7));Check(Locksmith.SealedVentsStatic.Contains(8)&&Locksmith.SealedVentsStatic.Contains(7));});
Test("invalid vent payload count rejected",()=>{var a=new Locksmith(PC(1,CustomRoles.Locksmith));bool rejected=false;try{a.ReceiveRPC(new(1,0f,1000000));}catch(System.IO.InvalidDataException){rejected=true;}Check(rejected);});
Test("coroner murder hook registered",()=>{var c=new Coroner(PC(1,CustomRoles.Coroner));c.Add();Check(CustomRoleManager.OnMurderPlayerOthers.Count==1);});
Test("coroner defaults to private report",()=>Check(!Coroner.OptionShowReport.GetBool()));
Test("multiple coroners keep reports separate",()=>{var c=new Coroner(PC(1,CustomRoles.Coroner));var other=new Coroner(PC(2,CustomRoles.Coroner));var dead=PC(4);Coroner.AllKillRecords[4]=new(){VictimId=4,DeathTime=70,RoomName="Room"};c.OnReportDeadBody(c.Player,dead.Data);GameStates.IsMeeting=true;other.OnStartMeeting();c.OnStartMeeting();LateTask.Run();Check(Utils.Sent.Count==1&&Utils.Sent[0].To==1);});
Test("coroner disconnected target never broadcasts",()=>{var c=new Coroner(PC(1,CustomRoles.Coroner));var dead=PC(4);Coroner.AllKillRecords[4]=new(){VictimId=4,DeathTime=70,RoomName="Room"};c.OnReportDeadBody(c.Player,dead.Data);GameStates.IsMeeting=true;c.OnStartMeeting();c.Player.Data.Disconnected=true;LateTask.Run();Check(Utils.Sent.Count==0);});
Test("coroner reused player ID never receives old report",()=>{var c=new Coroner(PC(1,CustomRoles.Coroner));var dead=PC(4);Coroner.AllKillRecords[4]=new(){VictimId=4,DeathTime=70,RoomName="Room"};c.OnReportDeadBody(c.Player,dead.Data);GameStates.IsMeeting=true;c.OnStartMeeting();PC(1);LateTask.Run();Check(Utils.Sent.Count==0);});
Test("coroner invalid ClientId never broadcasts",()=>{var c=new Coroner(PC(1,CustomRoles.Coroner));var dead=PC(4);Coroner.AllKillRecords[4]=new(){VictimId=4,DeathTime=70,RoomName="Room"};c.OnReportDeadBody(c.Player,dead.Data);GameStates.IsMeeting=true;c.OnStartMeeting();c.Player.ClientId=-1;LateTask.Run();Check(Utils.Sent.Count==0);});
Test("coroner opt-in public report supported",()=>{Coroner.OptionShowReport.Value=1;var c=new Coroner(PC(1,CustomRoles.Coroner));var dead=PC(4);Coroner.AllKillRecords[4]=new(){VictimId=4,DeathTime=70,RoomName="Room"};c.OnReportDeadBody(c.Player,dead.Data);GameStates.IsMeeting=true;c.OnStartMeeting();LateTask.Run();Check(Utils.Sent.Single().To==255);});
Console.WriteLine($"RESULT {passed} passed, 0 failed (actual role sources, Unity/network substitutes)");}}
